<template><div class="page"><div><h1 class="page-title">系统运行</h1><p class="page-subtitle">WebSocket、Go Runtime、基础设施与错误状态</p></div><div v-if="error" class="system-error">{{error}}</div><div class="kpi-grid"><MetricCard label="WebSocket 连接" :value="d.runtime?.ws_connections" hint="当前长连接" :icon="RadioTower"/><MetricCard label="Goroutine" :value="d.runtime?.goroutines" hint="Go Runtime" :icon="Cpu" tone="purple"/><MetricCard label="API P95" :value="d.runtime?.api_p95_ms" suffix="ms" hint="HTTP API" :icon="Gauge" tone="success"/><MetricCard label="错误率" :value="d.runtime?.error_rate" suffix="%" hint="最近 5 分钟" :icon="TriangleAlert" tone="warning"/></div><section class="app-card system-card"><div class="panel-head"><div><h3>依赖服务</h3><p>健康检查应由后端带超时并发执行</p></div><button class="btn btn-sm" @click="load"><RefreshCw :size="13"/>重新检测</button></div><div class="service-grid"><div v-for="s in d.health||[]" :key="s.name"><div class="service-icon"><Server :size="17"/></div><div><b>{{s.name}}</b><span>{{s.latency_ms}} ms</span></div><StatusBadge :tone="s.status==='healthy'?'success':s.status==='degraded'?'warning':'danger'" dot>{{s.status}}</StatusBadge></div><div v-if="!(d.health||[]).length" class="no-data">暂无系统健康数据</div></div></section><div class="two-col"><section class="app-card system-card"><div class="panel-head"><div><h3>容量与资源</h3><p>适合后续接 Prometheus / pprof</p></div></div><div class="resource"><div><span>Heap Alloc</span><b>{{d.runtime?.heap_mb??'—'}} MB</b><i style="--p:58%"></i></div><div><span>Goroutines</span><b>{{d.runtime?.goroutines??'—'}}</b><i style="--p:42%"></i></div><div><span>WS Connections</span><b>{{d.runtime?.ws_connections??'—'}}</b><i style="--p:36%"></i></div></div></section><section class="app-card system-card"><div class="panel-head"><div><h3>运行建议</h3><p>根据当前架构优先监控</p></div></div><ul><li>慢客户端与发送队列积压</li><li>WebSocket 异常断开率</li><li>Agent / Embedding 外部 API P95</li><li>Kafka consumer lag 与 Redis 状态</li><li>Qdrant 查询耗时和向量写入失败率</li></ul></section></div></div></template>
<script setup>import{onMounted,ref}from'vue';import{RadioTower,Cpu,Gauge,TriangleAlert,RefreshCw,Server}from'lucide-vue-next';import MetricCard from'../../components/admin/MetricCard.vue';import StatusBadge from'../../components/common/StatusBadge.vue';import{adminApi}from'../../api/admin.js';const d=ref({}),error=ref('');async function load(){error.value='';try{d.value=await adminApi.systemOverview()}catch(e){d.value={};error.value=e.message}}onMounted(load)</script>
<style scoped>.page{display:grid;gap:14px}.system-card{padding:18px}.panel-head{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:14px}.panel-head h3{margin:0;font-size:14px}.panel-head p{margin:4px 0 0;color:var(--text-3);font-size:10px}.service-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.service-grid>div{border:1px solid var(--line);border-radius:10px;padding:12px;display:grid;grid-template-columns:34px 1fr auto;align-items:center;gap:9px}.service-icon{width:34px;height:34px;border-radius:9px;background:var(--surface-soft);display:grid;place-items:center;color:var(--text-2)}.service-grid b,.service-grid span{display:block;font-size:11px}.service-grid span{font-size:9px;color:var(--text-3);margin-top:3px}.no-data{grid-column:1/-1!important;display:block!important;text-align:center;color:var(--text-3)}.resource{display:grid;gap:14px}.resource>div{display:grid;grid-template-columns:1fr auto;gap:7px;font-size:11px}.resource span{color:var(--text-2)}.resource i{grid-column:1/-1;height:6px;background:var(--surface-muted);border-radius:99px;overflow:hidden}.resource i:before{content:"";display:block;height:100%;width:var(--p);background:var(--primary);border-radius:99px}ul{margin:0;padding-left:18px;color:var(--text-2);font-size:11px;line-height:2}@media(max-width:1000px){.service-grid{grid-template-columns:1fr 1fr}}.system-error{padding:10px 12px;border-radius:9px;background:var(--danger-soft);color:var(--danger);font-size:11px}</style>
